def predict(X, Y, U, j, family, a=0., sign=1):
    k, p = (j+1)%4, (j-1)%4
    def design(z):
        q, n, b = z[:, j], z[:, k], z[:, p]
        base = np.column_stack((np.ones(len(z)), q, n, b, q*n, q**3))
        if family == 'square':
