        if family == 'mixed cubic':
            return np.column_stack((base, q*q*n, q*n*n, q*n*b))
        if family == 'rational':
            return base/(1+a*(q+sign*n)**2)[:,None]
        return base
    return design(U) @ np.linalg.lstsq(design(X), Y[:,j], rcond=None)[0]

